	}

	switch message.Type {
	case storepb.InboxMessage_MEMO_COMMENT:
		payload := message.GetMemoComment()
		if payload == nil {
			return false
		}
		return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
